import rclpy
from rclpy.node import Node

def main():
    rclpy.init()                                #初始化recl模块,分配资源
    node = Node("python_node")                  #创建节点
    node.get_logger().info("你好 Python ROS2")  #打印日志
    rclpy.spin(node)                            #插入节点，循环运行阻塞运行
    rclpy.shutdown()

#以下语句仅仅只是用来让python解释器知道，如果当前这个脚本是被直接执行的话，那么就执行main()函数
#如果是被其他脚本引用的话，就不执行main()函数
#原因是因为python是解释型语言，在执行时是从上到下的，不是默认从main()函数开始执行的
#那么就会出现一种情况，如果脚本中有很多代码时，有些函数可能不需要执行，有些函数必须在某些函数执行执行，
#那么就要通过这种方式来控制脚本中那些代码执行，那些代码不执行
#具体的原理是，当脚本被直接执行时，__name__特殊变量被赋值为'__main__',当脚本被其他脚本导出时，__name__特殊变量
#被赋值为脚本的名字
if __name__ == "__main__":
    main()